function get( root, path ){
	var i, c,
		space,
		nextSpace,
		curSpace = root;

	if ( !root ){
		return root;
	}

	space = parse(path);
	if ( space.length ){
		for( i = 0, c = space.length; i < c; i++ ){
			nextSpace = space[i];

			if (nextSpace === '__proto__'){
				return null;
			}

			if ( isUndefined(curSpace[nextSpace]) ){
				return;
			}

			curSpace = curSpace[nextSpace];
		}
	}

	return curSpace;
}

